  "29_3": "<svg viewBox=\"0 0 800 300\" xmlns=\"http://www.w3.org/2000/svg\" style=\"width:100%;height:auto\"><rect width=\"800\" height=\"300\" fill=\"#1e293b\" rx=\"8\"/><text x=\"400\" y=\"28\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"13\" font-family=\"sans-serif\">AI 安全的挑战</text><defs><marker id=\"ah\" markerWidth=\"8\" markerHeight=\"6\" refX=\"8\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L8,3 L0,6\" fill=\"#334155\"/></marker></defs><rect x=\"50\" y=\"50\" width=\"320\" height=\"100\" rx=\"8\" fill=\"none\" stroke=\"#ec4899\" stroke-width=\"2\"/><text x=\"210\" y=\"75\" fill=\"#ec4899\" font-size=\"11\" font-family=\"sans-serif\" font-weight=\"bold\" text-anchor=\"middle\">AI 面临的安全威胁</text><text x=\"210\" y=\"100\" fill=\"#94a3b8\" font-size=\"9\" font-family=\"sans-serif\" text-anchor=\"middle\">对抗攻击：微小改动欺骗 AI</text><text x=\"210\" y=\"120\" fill=\"#94a3b8\" font-size=\"9\" font-family=\"sans-serif\" text-anchor=\"middle\">数据投毒：污染训练数据</text><rect x=\"430\" y=\"50\" width=\"320\" height=\"100\" rx=\"8\" fill=\"none\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"590\" y=\"75\" fill=\"#10b981\" font-size=\"11\" font-family=\"sans-serif\" font-weight=\"bold\" text-anchor=\"middle\">防御措施</text><text x=\"590\" y=\"100\" fill=\"#94a3b8\" font-size=\"9\" font-family=\"sans-serif\" text-anchor=\"middle\">对抗训练：让 AI 学会抵抗攻击</text><text x=\"590\" y=\"120\" fill=\"#94a3b8\" font-size=\"9\" font-family=\"sans-serif\" text-anchor=\"middle\">数据清洗：确保训练数据安全</text><rect x=\"100\" y=\"175\" width=\"600\" height=\"75\" rx=\"8\" fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"2\"/><text x=\"400\" y=\"200\" fill=\"#f59e0b\" font-size=\"11\" font-family=\"sans-serif\" font-weight=\"bold\" text-anchor=\"middle\">安全是 AI 发展的底线，不是事后补丁</text><text x=\"400\" y=\"222\" fill=\"#94a3b8\" font-size=\"9\" font-family=\"sans-serif\" text-anchor=\"middle\">从设计阶段就要考虑安全</text></svg>",
